package dev.kuan.kuanperion.automation.pest;
import dev.kuan.kuanperion.automation.*;import java.util.*;
public final class PestBaitButtonTransferTest {
 static final long S=1_000_000_000L;static final ItemSnapshot AIR=PestBaitButtonViewTest.AIR;static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static final class H {
  AutomationContext ctx=new AutomationContext(1,true,true,Set.of());java.util.function.Supplier<AutomationContext> read=()->ctx;final AutomationCoordinator coordinator=new AutomationCoordinator();final AutomationSession session=new AutomationSession(coordinator,()->ctx,()->{},()->{});final AutomationSession.Handle owner=session.begin(AutomationFeature.PEST,0,120*S);final InventoryReceipts items=new InventoryReceipts();final CursorReceipts cursors=new CursorReceipts();final Object level=new Object(),identity=new Object();
  final PestTrapTarget target=PestBaitButtonViewTest.TARGET;final ItemSnapshot marker=PestBaitButtonViewTest.role("Click to insert bait!");Map<Integer,ItemSnapshot> inv=PestBaitButtonPlanTest.inventory(16);MenuSnapshot menu;ItemSnapshot carried=AIR;PestTrapObservation traps=new PestTrapObservation(Set.of(),true,Set.of(1),true);final PestBaitButtonTransfer proof=new PestBaitButtonTransfer(session,coordinator,items,cursors,()->read.get());long now=S;
  H(){var opening=items.stamp(1);var cursorOpening=cursors.openingStamp(1,0);refresh(marker);for(var slot:menu.slots())items.observe(1,7,slot.index(),slot.item());cursors.observe(1,7,AIR,now);ctx=new AutomationContext(1,true,true,Set.of(AutomationContext.Blocker.MENU));var plan=PestBaitButtonPlan.select(new PestBaitButtonPlan.Rules("TASTY_CHEESE",16,64,Set.of()),inv,64).orElseThrow();var role=PestBaitButtonView.initial(menu,target,traps).orElseThrow();check(proof.begin(owner,plan,target,role,frame(),opening,cursorOpening,now),"private full-source plan and fresh original opening");}
  void refresh(ItemSnapshot role){var slots=new ArrayList<MenuSnapshot.Slot>();for(int i=0;i<27;i++)slots.add(new MenuSnapshot.Slot(i,i==13?role:AIR));for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(27+i,inv.get(i<27?i+9:i-27),true));menu=new MenuSnapshot(1,7,1,"Mouse Trap",27,slots);}
  PestBaitButtonTransfer.Frame frame(){return new PestBaitButtonTransfer.Frame(1,now,level,identity,menu,inv,carried,traps,List.of(target));}
  PestBaitButtonTransfer.Action send(){var action=proof.arm(frame(),now).orElseThrow();check(action.claim(owner,frame(),now),"native gate consumes exact original private action once");check(!action.claim(owner,frame(),now),"same native action never replayed");check(proof.sent(action,GuardedMenuAction.Result.SENT,now),"one native send");return action;}
  void picked(){send();now=2*S;inv.put(9,AIR);carried=PestBaitButtonPlanTest.bait(16);refresh(marker);items.observe(1,0,9,AIR);items.observe(1,7,27,AIR);cursors.observe(1,7,carried,now);proof.poll(frame(),now);check(proof.state()==PestBaitButtonTransfer.State.READY&&proof.step()==PestBaitButtonTransfer.Step.DEPOSIT,"paired source removal plus server own cursor, not prediction");}
  void deposited(){picked();send();now=3*S;carried=PestBaitButtonPlanTest.bait(12);refresh(marker);cursors.observe(1,7,carried,now);traps=new PestTrapObservation(Set.of(),true,Set.of(),true);proof.poll(frame(),now);check(proof.state()==PestBaitButtonTransfer.State.READY&&proof.step()==PestBaitButtonTransfer.Step.RETURN&&proof.consumed()==4,"source-button consume count from actual own cursor, fresh NoBait removal, no guessed capacity");}
 }
 static void updatedRole(){
  var h=new H();h.picked();h.send();h.now=3*S;h.carried=PestBaitButtonPlanTest.bait(12);var updated=PestBaitButtonViewTest.role("Current bait: Tasty Cheese","Click to remove bait!");h.refresh(updated);h.items.observe(1,7,13,updated);h.cursors.observe(1,7,h.carried,h.now);h.traps=new PestTrapObservation(Set.of(),true,Set.of(),true);h.proof.poll(h.frame(),h.now);check(h.proof.state()==PestBaitButtonTransfer.State.READY,"new server-proven role after deposit");h.send();h.now=4*S;h.inv.put(9,PestBaitButtonPlanTest.bait(12));h.carried=AIR;h.refresh(updated);h.items.observe(1,0,9,h.inv.get(9));h.items.observe(1,7,27,h.inv.get(9));h.cursors.observe(1,7,AIR,h.now);h.proof.poll(h.frame(),h.now);check(h.proof.state()==PestBaitButtonTransfer.State.CONFIRMED,"return touches player source/cursor only; no unsolicited second GUI-role packet is required");
 }
 static void reentrantArm(){
  var h=new H();h.picked();PestBaitButtonTransfer.Action[] accepted={null};h.read=()->{h.read=()->h.ctx;accepted[0]=h.proof.arm(h.frame(),h.now).orElseThrow();return h.ctx;};check(h.proof.arm(h.frame(),h.now).isEmpty()&&accepted[0].claim(h.owner,h.frame(),h.now),"old reentrant read cannot replace a newly accepted private action");
 }
 static void reentrantSent(){
  var h=new H();h.picked();var action=h.proof.arm(h.frame(),h.now).orElseThrow();check(action.claim(h.owner,h.frame(),h.now),"send fixture claim");h.read=()->{h.read=()->h.ctx;check(h.proof.sent(action,GuardedMenuAction.Result.SENT,h.now),"new nested result accepted");return h.ctx;};check(!h.proof.sent(action,GuardedMenuAction.Result.SENT,h.now)&&h.proof.state()==PestBaitButtonTransfer.State.AWAITING,"one action cannot accept native result twice across a context callback");
 }
 static void reentrantPoll(){
  var h=new H();h.picked();h.send();h.now=3*S;h.carried=PestBaitButtonPlanTest.bait(12);h.refresh(h.marker);h.cursors.observe(1,7,h.carried,h.now);h.traps=new PestTrapObservation(Set.of(),true,Set.of(),true);var wrong=new HashMap<>(h.inv);wrong.put(42,PestBaitButtonPlanTest.bait(1));var stale=new PestBaitButtonTransfer.Frame(1,h.now,h.level,h.identity,h.menu,wrong,h.carried,h.traps,List.of(h.target));h.read=()->{h.read=()->h.ctx;h.proof.poll(h.frame(),h.now);return h.ctx;};h.proof.poll(stale,h.now);check(h.proof.state()==PestBaitButtonTransfer.State.READY&&h.proof.step()==PestBaitButtonTransfer.Step.RETURN,"old frame cannot cancel a newer accepted server-receipt transition");
 }
 public static void main(String[]args){
  if(args.length>0){switch(args[0]){case "role"->updatedRole();case "arm"->reentrantArm();case "sent"->reentrantSent();case "poll"->reentrantPoll();}return;}
  updatedRole();reentrantArm();reentrantSent();reentrantPoll();
  var h=new H();h.deposited();h.send();h.now=4*S;h.inv.put(9,PestBaitButtonPlanTest.bait(12));h.carried=AIR;h.refresh(h.marker);h.items.observe(1,0,9,h.inv.get(9));h.cursors.observe(1,7,AIR,h.now);h.proof.poll(h.frame(),h.now);check(h.proof.state()!=PestBaitButtonTransfer.State.CONFIRMED,"canonical return alone not enough");h.items.observe(1,7,27,h.inv.get(9));h.proof.poll(h.frame(),h.now);check(h.proof.state()==PestBaitButtonTransfer.State.CONFIRMED&&h.proof.consumed()==4&&h.session.isCurrent(h.owner),"exact own remainder restored, paired destination/empty cursor, original root retained");
  h=new H();h.picked();h.send();h.now=3*S;h.carried=h.marker;h.refresh(PestBaitButtonPlanTest.bait(16));h.proof.poll(h.frame(),h.now);check(h.proof.state()==PestBaitButtonTransfer.State.AWAITING,"exact GUI-marker local swap prediction waits without repair/action");h.cursors.observe(1,7,h.marker,h.now);h.proof.poll(h.frame(),h.now);check(h.proof.state()==PestBaitButtonTransfer.State.UNCERTAIN,"server-confirmed GUI marker is NOT owned bait");
  h=new H();h.picked();h.session.cancel(3*S);check(h.proof.arm(h.frame(),h.now).isEmpty(),"revoked parent cannot mint carried-item action");
  h=new H();h.deposited();h.send();h.now=4*S;h.inv.put(9,PestBaitButtonPlanTest.bait(12));h.carried=AIR;h.refresh(h.marker);h.items.observe(1,0,9,h.inv.get(9));h.items.observe(1,7,27,h.inv.get(9));h.cursors.observe(1,7,AIR,h.now);h.proof.poll(h.frame(),h.now);
  check(h.proof.confirmedStillMatches(h.frame(),h.now),"closing revalidates full settled state under original root");
  h.inv.put(42,PestBaitButtonPlanTest.bait(1));check(!h.proof.confirmedStillMatches(h.frame(),h.now),"confirmed state is not authority after unrelated inventory drift");
  System.out.println("PestBaitButtonTransferTest: PASS");
 }
}
